function isoDate(date) {
  const y = date.getFullYear(), m = String(date.getMonth()+1).padStart(2,"0"), d = String(date.getDate()).padStart(2,"0")
  return `${y}-${m}-${d}`
}
function parseLocal(iso) { const [y,m,d] = String(iso).split("-").map(Number); return new Date(y,m-1,d) }
function mondayOf(date = new Date()) { const d = new Date(date.getFullYear(),date.getMonth(),date.getDate()); const day=(d.getDay()+6)%7; d.setDate(d.getDate()-day); return isoDate(d) }
function addDays(iso, n) { const d=parseLocal(iso); d.setDate(d.getDate()+n); return isoDate(d) }
function fmtDate(iso) { const d=parseLocal(iso); return `${String(d.getDate()).padStart(2,"0")}/${String(d.getMonth()+1).padStart(2,"0")}` }
function requestClass(value) { return value === "OFF" ? "off" : value.startsWith("MUST_") ? "must" : value.startsWith("PREFER_") ? "prefer" : "" }
function shiftCode(row) { if (!row) return "OFF"; if (row.shift === "MORNING") return row.start_time === "07:00" ? "M07" : "M06"; if (row.shift === "AFTERNOON") return "A"; return "OFF" }
function pairType(rule) { return rule.relation_type || (rule.max_same_shifts_per_week != null ? "MAX" : "UNLIMITED") }
function pairCount(rule) { return rule.count ?? rule.max_same_shifts_per_week ?? "" }
function pairReceiving(rule) { if (rule.receiving_relation) return rule.receiving_relation; return rule.receiving_day_allowed === false ? (rule.level === "HARD" ? "NEVER" : "AVOID") : "NORMAL" }
function relationNeedsCount(type) { return ["MAX","MIN","EXACT","PREFER_TOGETHER"].includes(type) }
function authHeaders(token, json=false) { const h = {}; if(token) h.Authorization=`Bearer ${token}`; if(json) h["Content-Type"]="application/json"; return h }
async function apiJson(path, options={}) { const res=await fetch(`${API}${path}`,options); let data=null; try{data=await res.json()}catch{}; if(!res.ok){const detail=data?.detail; const message=typeof detail==="string"?detail:(detail?.message||`HTTP ${res.status}`); const error=new Error(message); error.status=res.status; error.detail=detail; throw error} return data }

function defaultConfig(weekStart, employees=DEFAULT_EMPLOYEES) {
  const staffing = Array.from({length:7},(_,i)=>({date:addDays(weekStart,i),morning:i===0?3:2,afternoon:i===0?2:3}))
  const receiving_days = [1,3,5].map(i=>({date:addDays(weekStart,i),count:3}))
  const manager = employees.find(e=>e.role==="STORE_MANAGER" && e.active) || employees.find(e=>e.active)
  const fixed_weekday_rules = manager ? [
    {employee_id:manager.id,weekday:0,shift:"MORNING",level:"HARD",source:"REGIONAL"},
    {employee_id:manager.id,weekday:1,shift:"AFTERNOON",level:"HARD",source:"REGIONAL"},
  ] : []
  return {store_label:"1885",week_start:weekStart,employees,staffing,receiving_days,requests:[],fixed_weekday_rules,employee_rules:DEFAULT_RULES.filter(r=>employees.some(e=>e.id===r.employee_id)),manager_trend:{enabled:true,scores:DEFAULT_MANAGER_TREND.map(r=>({...r}))},pairing_rules:[],morning_time_overrides:[]}
}

function hydrateScheduleConfig(raw) {
  if (!raw || typeof raw !== "object") return raw
  const employees = Array.isArray(raw.employees) ? raw.employees : []
  const manager = employees.find(e=>e.active && e.role==="STORE_MANAGER")
  const trend = raw.manager_trend && Array.isArray(raw.manager_trend.scores) && raw.manager_trend.scores.length
    ? raw.manager_trend
    : {enabled:true,scores:DEFAULT_MANAGER_TREND.map(r=>({...r}))}
  const fixed = Array.isArray(raw.fixed_weekday_rules) ? raw.fixed_weekday_rules : []
  const userRules = fixed.filter(r=>{
    if(r.source==="REGIONAL") return false
    if(!manager || r.employee_id!==manager.id || r.level!=="HARD") return true
    return !((Number(r.weekday)===0&&r.shift==="MORNING")||(Number(r.weekday)===1&&r.shift==="AFTERNOON"))
  })
  const regional = manager ? [
    {employee_id:manager.id,weekday:0,shift:"MORNING",level:"HARD",source:"REGIONAL"},
    {employee_id:manager.id,weekday:1,shift:"AFTERNOON",level:"HARD",source:"REGIONAL"},
  ] : []
  return {...raw,manager_trend:trend,fixed_weekday_rules:[...regional,...userRules]}
}

